a, S = [5, 4, 3], 7
best = 0
for m in range(1 << len(a)):
    t = sum(v for i, v in enumerate(a)
            if m >> i & 1)
    if t <= S:
        best = ___(best, t)
print(best)

int[] a = {5, 4, 3};
int S = 7, best = 0;
for (int m = 0; m < (1 << a.length); m++) {
    int t = 0;
    for (int i = 0; i < a.length; i++)
        if ((m >> i & 1) == 1) t += a[i];
    if (t <= S) best = Math.___(best, t);
}
System.out.println(best);

